endpoints.requestExample:
curl -X POST "{{API_BASE}}/v1/chat/completions" \
  -H "Authorization: Bearer $NEW_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
  "model": "gpt-4o-mini",
  "messages": [
    {
      "role": "system",
      "content": "You are a concise assistant."
    },
    {
      "role": "user",
      "content": "Say hello in one sentence."
    }
  ],
  "temperature": 0.7,
  "stream": false
}'

